    public static Map<String, ModelPart> bake(ModelPart root) {
        Map<String, ModelPart> m = new HashMap<>();
        m.put("root", root);
        m.put("head", root.getChild("head"));
        for (String n : ORDER) m.put(n, m.get(PARENT.get(n)).getChild(n));
        return m;
    }

